import { useEffect, useState } from 'react';
import axios from '../api/axios';

export default function AdminPage() {
  const [clients, setClients] = useState([]);
  const [form, setForm] = useState({
    fullName: '',
    email: '',
    phone: '',
    notes: '',
    role: 'client',
    password: ''
  });

  // загрузка списка
  useEffect(() => {
    axios.get('/clients')
      .then(res => setClients(res.data))
      .catch(err => console.error(err));
  }, []);

  // добавление клиента
  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      const payload = { ...form };
      // сервер ждёт passwordHash, но мы можем отправить password и хэшировать на сервере
      const res = await axios.post('/clients', payload);
      setClients([...clients, res.data]);
      setForm({ fullName: '', email: '', phone: '', notes: '', role: 'client', password: '' });
    } catch (err) {
      alert(err.response?.data?.error || 'Ошибка создания');
    }
  };

  // обновление клиента
  const handleUpdate = async (id, updates) => {
    try {
      const res = await axios.put(`/clients/${id}`, updates);
      setClients(clients.map(c => c._id === id ? res.data : c));
    } catch (err) {
      alert('Ошибка обновления');
    }
  };

  // удаление клиента
  const handleDelete = async (id) => {
    try {
      await axios.delete(`/clients/${id}`);
      setClients(clients.filter(c => c._id !== id));
    } catch (err) {
      alert('Ошибка удаления');
    }
  };

  return (
    <main className="container section fade-in">
      <article className="card">
        <h2 className="h2">Админ‑панель</h2>

        {/* форма добавления */}
        <form className="form" onSubmit={handleCreate}>
          <input placeholder="ФИО" value={form.fullName} onChange={e => setForm({ ...form, fullName: e.target.value })} required />
          <input placeholder="Email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} required />
          <input placeholder="Телефон" value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} required />
          <input placeholder="Пароль" type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} required />
          <textarea placeholder="Заметки" value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} />
          <select value={form.role} onChange={e => setForm({ ...form, role: e.target.value })}>
            <option value="client">Клиент</option>
            <option value="admin">Админ</option>
          </select>
          <button type="submit">Добавить клиента</button>
        </form>

        {/* список клиентов */}
        <ul className="info-list">
          {clients.map(c => (
            <li key={c._id} className="info-list__item">
              <div>
                <strong>{c.fullName}</strong> ({c.role})<br />
                Email: {c.email}<br />
                Телефон: {c.phone}<br />
                Заметки: {c.notes || '—'}<br />
                Создан: {new Date(c.createdAt).toLocaleString()}<br />
                Обновлён: {new Date(c.updatedAt).toLocaleString()}
              </div>
              <button onClick={() => handleUpdate(c._id, { notes: 'Обновлено админом' })}>Редактировать</button>
              <button onClick={() => handleDelete(c._id)}>Удалить</button>
            </li>
          ))}
        </ul>
      </article>
    </main>
  );
}
